// th15_s7_w11 — TH15 v1.00b Stage 7 Extra，道中 GirlD04 第三编队
// 源: st07.ecl.txt MainSub07:1298-1301 (entry)
//     GirlD04:820-844、GirlD04_at:861-897 (dependency)
// Extra 取 !O → rank4。章节入口、ENM_CNT 刷怪门控、死亡掉落与出生动画按任务许可省略。
// 三组 GirlD04 是三个独立场景；本卡只保留 $I0=20 的第三只，不叠加前两组。

const TIME_LIMIT: int = 2824;   // 120 开场缓冲 + 2700 波窗口 + 4 启动余量
const OPENING_BUFFER: int = 120;

// 源 etSprite(0, 20, 3)：type20 → TH15_OVAL(672)，color 3，基础半径 7。
const TH15_OVAL: int = 672;

// 源 etDist(0,24) 叠加 ANIM a=1 的出生退位移 4*初速(=4*2.0=8)，沿弹角净推 16px。
const SPAWN_DIST: fx = 16fx;

// 源 GirlD04_at: %A 初值 %RANDRAD，每波减 3.883222rad = 40504 BAM。
const ANGLE_STEP: int = 40504;

// 源 EX 链: ANIM a=1(出生表现整体省略)；OFFSCREEN a=360,b=0；ANGLE_ACCEL a=120,
// r=0.01(每帧标量加速), s=±1deg/帧。120 帧后角速度与加速度同时归零。
xformdef GIRLD04_TURN(dir: angle) {
    offscreen_keep(360);
    set_ang_vel(dir);
    set_accel(0.01fx);
    wait(120);
    set_ang_vel(0deg);
    set_accel(0fx);
}

// 源 GirlD04_at (861-897)：wait60 后每 20 帧两波整周环，基角每波 -3.883222rad；
// 每第 7 个循环 $I0+1(上限 32)；C 从 1000 递减到 0 后 return。
async sub girl_shot() {
    wait(60);
    sh_reset(0);
    sh_sprite(0, TH15_OVAL, 3);       // etSprite(0,20,3)
    sh_aim(0, 0);                     // etAim(0,3): 固定方向整周环
    sh_ring(0, 1);
    sh_speed(0, 2fx, 0fx);            // etSpeed(0,2.0,0.2)，层数1只取首速
    sh_dist(0, SPAWN_DIST);           // etDist(0,24) + ANIM 退位移
    var a: int = rand(65536);         // %A = %RANDRAD
    var b: int = -1;
    var c: int = 1000;
    var n: int = 20;                  // $I0
    loop {
        b = b + 1;
        sh_count(0, n, 1);            // etCount(0,$I0,1)
        sh_xform(0, GIRLD04_TURN(1deg));
        sh_angle(0, (a as angle), 0deg);  // etAngle(0,%A,0)
        sh_fire(0);
        a = a - ANGLE_STEP;
        wait(20);
        sh_xform(0, GIRLD04_TURN(-1deg));
        sh_angle(0, (a as angle), 0deg);
        sh_fire(0);
        a = a - ANGLE_STEP;
        wait(20);
        if ((b % 7) == 6) && (n < 32) { n = n + 1; }
        c = c - 1;
        if c < 0 { break; }
    }
}

// 源 GirlD04 (820-844)：出生(0,-48)，向下 4.7 在 60 帧内减速到 0；
// 1200 帧后转向上，60 帧加速到 0.5；1800 帧后再 80 帧加速到 1.0；末段 wait(1000) 循环。
async sub girl_d04() {
    set_invuln(65535);                // 合成外壳：无敌存活路径，不接死亡回调/掉落
    set_hurtbox(16fx);                // setHurtbox(32,32): 第一值×0.5
    set_hitbox(12fx);                 // setHitbox(24,24): 第一值×0.5
    move_vel(0, 90deg, 4.7fx, EASE_LINEAR);
    move_speed(60, 0fx, EASE_QUAD_IN);    // moveSpeedTime(60,1,0.0)
    spawn girl_shot();                    // @GirlD04_at() async
    wait(1200);
    move_vel(0, -90deg, 0fx, EASE_LINEAR);
    move_speed(60, 0.5fx, EASE_QUAD_IN);  // moveSpeedTime(60,1,0.5)
    wait(600);
    move_speed(80, 1fx, EASE_QUAD_IN);    // moveSpeedTime(80,1,1.0)
    wait(60);
    loop { wait(1000); }                  // GirlD04_476/496 无限等待
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, -48fx, 10000, 0, 1000, 0, girl_d04);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
